#!/usr/bin/env node
/**
 * Route catalogue: every place a person can navigate to, read from the two route trees
 * (expo-router `apps/gurudevi-mobile/app`, TanStack Router `apps/gurudevi-web/spa/routes`). The file trees are the
 * truth; this writes them to `packages/core/src/routing/routeCatalog.generated.ts` so flows and
 * the navigator can check a route exists. `--check` fails when the generated file is out of date.
 */
import { readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, resolve } from 'node:path';

const ROOT = resolve(import.meta.dirname, '..');
const OUT = join(ROOT, 'packages/core/src/routing/routeCatalog.generated.ts');

const walk = (dir) =>
  readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    return statSync(path).isDirectory() ? walk(path) : [path];
  });

/** expo-router: every file is a route except layouts and `+` special files. Groups stay in. */
function mobileRoutes() {
  const app = join(ROOT, 'apps/gurudevi-mobile/app');
  return walk(app)
    .filter((f) => /\.tsx?$/.test(f) && !/\.(test|spec)\.tsx?$/.test(f))
    .map((f) => relative(app, f).replace(/\.tsx?$/, ''))
    .filter((r) => !r.split('/').some((s) => s === '_layout' || s.startsWith('+')))
    .map((r) => `/${r}`.replace(/\/index$/, '') || '/');
}

/**
 * TanStack Router: the router plugin writes every route's URL to `spa/generated/routeTree.gen.ts`
 * (`fullPaths`), so that file is read rather than the tree re-walked. Its `$param`, `$` (splat) and
 * `{-$param}` (optional) are written in the bracket form flows use: `[param]`, `[...splat]`, `[[...param]]`.
 */
function webRoutes() {
  const tree = readFileSync(join(ROOT, 'apps/gurudevi-web/spa/generated/routeTree.gen.ts'), 'utf8');
  const union = /fullPaths:\s*((?:\s*\|\s*'[^']*')+)/.exec(tree);
  if (!union) throw new Error('route-catalog: no `fullPaths` in routeTree.gen.ts');
  return [...union[1].matchAll(/'([^']*)'/g)].map(([, path]) => {
    const url = path
      .split('/')
      .map((s) =>
        s === '$'
          ? '[...splat]'
          : s.replace(/^\{-\$(.+)\}$/, '[[...$1]]').replace(/^\$(.+)$/, '[$1]'),
      )
      .join('/');
    return url.length > 1 ? url.replace(/\/$/, '') : url;
  });
}

const sorted = (routes) => [...new Set(routes)].sort();
const list = (routes) =>
  `[\n${sorted(routes)
    .map((r) => `  '${r}',`)
    .join('\n')}\n]`;
const body = `// Generated by scripts/route-catalog.mjs from the route trees. Do not edit; run
// \`node scripts/route-catalog.mjs\` after adding, moving or removing a route.

/** expo-router routes, with their groups, e.g. \`/(tabs)/workspace/[id]\`. */
export const MOBILE_ROUTES = ${list(mobileRoutes())} as const;

/** Web (TanStack Router) routes as URLs, e.g. \`/community/chat/[groupId]\`. */
export const WEB_ROUTES = ${list(webRoutes())} as const;
`;

if (process.argv.includes('--check')) {
  const current = (() => {
    try {
      return readFileSync(OUT, 'utf8');
    } catch {
      return '';
    }
  })();
  if (current !== body) {
    console.error('route-catalog: out of date. Run `node scripts/route-catalog.mjs`.');
    process.exit(1);
  }
  console.log('route-catalog: up to date.');
} else {
  writeFileSync(OUT, body);
  console.log(`route-catalog: ${mobileRoutes().length} mobile, ${webRoutes().length} web routes.`);
}
